-- 과거 구간(9/1~9/18) 예정된 상담 시드 — 자동 생성 파일(직접 고치지 말 것).
-- 생성: node scripts/demo-consultation-seed/generate-past-scheduled-sql.mjs
-- ⚠️ 별도 승인(이지현) 전에는 공유 DB 에서 실행하지 않는다. 한 트랜잭션이고, 이미 있으면(같은 id) 건너뛰고, 검증이 어긋나면 전체가 취소된다.
-- 내용: parent_consultations(status='preparing') 34건 = 학생 상담(상담 대상 '학생 본인') 23 + 학부모 상담 11.
--   id 는 공용 시드 패턴(60000000-0000-4000-8000-000000000101~), 담임 계정 소유라서 방문자에게 공용으로 보인다.
--   기존 예정 45건·완료 6건은 건드리지 않는다. INSERT 만 한다(UPDATE·DELETE 없음). 롤백: 아래 id 범위 DELETE (예정 상태라 가드 트리거가 막지 않는다).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

do $$
begin
  if (select count(*) from public.enrollments where id::text like '40000000-0000-4000-8000-0000000000__') < 20 then
    raise exception '시드 실패: 시드 학생 20명(enrollments)이 있어야 한다';
  end if;
  if not exists (select 1 from public.class_teachers where teacher_id = '1dfa3467-2cba-4e59-a834-6dabb7a77363') then
    raise exception '시드 실패: 시드 담임 계정이 없다';
  end if;
end;
$$;

on conflict (id) do nothing;

do $$
declare
  added integer;
begin
  select count(*) into added from public.parent_consultations where id::text >= '60000000-0000-4000-8000-000000000101' and id::text <= '60000000-0000-4000-8000-000000000134' and status = 'preparing';
  if added <> 34 then
    raise exception '시드 검증 실패: 새 예정 상담이 34건이어야 하는데 % 건이다', added;
  end if;
  if (select count(*) from public.parent_consultations where status = 'preparing' and counterpart = '학생 본인' and id::text >= '60000000-0000-4000-8000-000000000101') <> 23 then
    raise exception '시드 검증 실패: 학생 상담 수가 다르다';
  end if;
end;
$$;

commit;

